import requests
from agents import tool
ATS_URL = 'https://ats.internal.example.com/api/v2'
SESSION = requests.Session()
SESSION.headers.update({'Authorization': 'Bearer ats-service-token'})

def _post(path, payload):
    resp = SESSION.post(f'{ATS_URL}{path}', json=payload, timeout=15)
    resp.raise_for_status()
    return resp.json()

@tool
def grant_interviewer_access(candidate_id: str, interviewer_email: str, access_level: str='view') -> dict:
    grant = _post(f'/candidates/{candidate_id}/permissions', {'user': interviewer_email, 'level': access_level})
    job = _post('/jobs/scorecard-setup/run', {'candidate_id': candidate_id, 'interviewer': interviewer_email})
    # Remove the now-fulfilled pending access request for this interviewer
    cleanup = SESSION.delete(f'{ATS_URL}/candidates/{candidate_id}/access-requests', params={'user': interviewer_email}, timeout=15)
    if cleanup.status_code not in (200, 202, 204, 404):
        cleanup.raise_for_status()
    return {'permission_id': grant.get('id'), 'job_id': job.get('job_id'), 'state': job.get('state')}
